INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('shang','商','["商","殷","殷商"]',NULL,NULL,'cn','east_asia',-1600,1,NULL,'year',-1046,1,NULL,'year',-19188,-12540,'ochre',NULL,NULL,'断代工程：商始约前1600年，盘庚迁殷约前1300年，武王克商前1046年。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('xia','夏','["夏","夏后氏"]',NULL,NULL,'cn','east_asia',-2070,1,NULL,'year',-1600,12,NULL,'month',-24828,-19177,'ochre',NULL,NULL,'夏的年代常采用夏商周断代工程所定约前2070年至前1600年。夏王世系及在位年数主要见于今本《竹书纪年》等传世文献，具体年代仍有争议；桀的在位年数另有《帝王世纪》五十二年说。相、少康之间，传世文献记有穷后羿与寒浞据夏政。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-east','东周','["周"]',NULL,'{"periods":[{"rank":"王","start":{"year":-770,"month":1,"confidence":"year"},"end":{"year":-256,"month":12,"confidence":"month"}}]}','cn','east_asia',-770,1,NULL,'year',-256,12,NULL,'month',-9228,-3049,'ochre',NULL,NULL,'平王东迁至秦灭周。前770–前750年与携王二王并立，后世以平王为正统。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('zhou-west','西周','["周"]',NULL,'{"periods":[{"rank":"王","start":{"year":-1046,"month":1,"confidence":"year"},"end":{"year":-771,"month":12,"confidence":"month"}}]}','cn','east_asia',-1046,1,NULL,'year',-771,12,NULL,'month',-12540,-9229,'ochre',NULL,NULL,'武王克商至犬戎破镐。列王年取夏商周断代工程《夏商周年表》。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bao-si','褒姒','zhou-west','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','周幽王宠妃，传说与烽火戏诸侯、犬戎之祸相关；犬戎攻入镐京后幽王与太子被杀，褒姒下落不详；“烽火戏诸侯”细节存疑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/褒姒"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bi-gan','比干','shang','[]','子',NULL,NULL,NULL,NULL,NULL,-1046,1,NULL,'year','["政治家","宗室"]','商末少师，文丁之子、帝辛叔父。《论语》与微子、箕子并称殷有三仁。传说强谏被剖心。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/比干"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('bo-yi','伯益',NULL,'["益","柏翳","大费"]','嬴',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','舜禹时虞官，佐禹治水；禹卒后一度受禅，传统记载启继位而益避居。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伯益"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('da-ji','妲己','shang','[]',NULL,NULL,NULL,NULL,NULL,NULL,-1046,1,NULL,'year','["后妃"]','妲己是商末传说中有苏氏之女，嫁予帝辛。关于她诱使帝辛施政、导致亡国的情节主要见于后世叙事，缺乏同时代材料印证，不能视为已证实的个人史实。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/妲己"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-hao','妇好','shang','["帚好"]',NULL,NULL,NULL,NULL,NULL,NULL,-1200,1,NULL,'year','["王后","军事家"]','武丁配偶，甲骨所见女将、祭司，殷墟有墓。生年不详，卒于武丁在世时。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/妇好"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('fu-yue','傅说','shang','["傅說"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','武丁之相。传说原在傅岩版筑为胥靡，武丁梦得圣人而举以为相，助成武丁中兴。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/傅说"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gan-pan','甘盘','shang','["甘盤"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','小乙、武丁时大臣。传说小乙命其傅武丁；武丁即位后为卿士，不久卒，傅说继之。《尚书·君奭》以之与伊尹、伊陟并称。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/甘盘"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gao-yao','皋陶',NULL,'["咎繇"]','偃',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','尧舜禹时掌刑之臣，传说制五刑、造狱。禹曾欲禅位于他，先禹而卒。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皋陶"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-longpang','关龙逢','xia','["关龙逄","龙逢"]',NULL,NULL,NULL,NULL,NULL,NULL,-1600,1,NULL,'year','["政治家"]','夏桀时谏臣。传说桀通宵宴乐，关龙逢进黄图强谏被杀。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/关龙逢"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('guan-zhong','管仲','zhou-east','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','春秋齐国政治家，名夷吾，字仲，颍上人。早年辅佐公子纠，齐桓公即位后任相，改革赋税、军政与行政制度，帮助齐国富强并成为春秋首位霸主。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/管仲"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('gun','鲧','xia','["崇伯鲧","梼杌"]','姒','崇',NULL,NULL,NULL,NULL,-2070,1,NULL,'year','["政治家"]','禹之父，崇伯。传说奉尧命障洪水九年不成，后被殛于羽山。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/鲧"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-jiao','浇','xia','["过浇","奡"]','妘','寒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["将领"]','寒浞之子，处过，故称过浇。《左传》载其灭斟灌、斟鄩并杀相，后为少康遣女艾所灭。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/浇"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-zhuo','浞','xia','["浞","韩浞"]','妘','寒',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','寒氏，名浞，妘姓。伯明氏谗子弟，后羿用为相，旋杀羿代有穷；使浇灭相。后为少康、靡所灭。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/寒浞"}]',NULL,NULL,'寒浞','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hou-min','后缗','xia','["缗"]',NULL,'有仍',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','有仍氏女，夏后相之妻。相为浇所灭时方娠，逃出自窦，归于有仍，生少康。见《左传·哀公元年》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/后缗"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('hou-yi','后羿','xia','["羿","夷羿","有穷后羿"]',NULL,'有穷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','有穷氏首领，善射。《左传》载其自鉏迁穷石，因夏民以代夏政，不修民事，为寒浞所杀。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/后羿_(夏朝)"}]',NULL,NULL,'后羿','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ban','班','zhou-east','["周匡王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周顷王之子，前612—前607年在位。其时周王室已难主导诸侯政治，国势与王畿规模有限；传世史籍对其个人政事记载较少，死后由其弟周定王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周匡王"}]','匡',NULL,'匡王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-bian','扁','zhou-east','["周显王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周烈王之弟，前368—前321年在位，是东周在位较久的天子。战国七雄相继称王，周王室失去对诸侯的实际控制；前344年魏惠王在逢泽会诸侯称王，显示天子名号已难独尊。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周显王"}]','显',NULL,'显王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-chang','昌','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["西伯","君主"]','商末周部族领袖，周武王之父。受商封为西伯，发展周人势力并经营岐周；周人追尊为文王，其政治与军事基础由武王承接，最终灭商建周。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周文王"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-dan','旦','zhou-west','[]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','周公旦，武王之弟，成王初摄政，东征平三监；摄政七年后还政成王，封鲁国而留居周都；后世将制礼作乐等传统归于周公。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周公旦"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ding','定','zhou-east','["周慎靓王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周显王之子，前320—前315年在位。战国后期秦、齐等国势力迅速增强，周王室日益依附于王畿诸侯；其子周赧王继位后，周室最终在秦国扩张中灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周慎靓王"}]','慎靓',NULL,'慎靓王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-fa','发','zhou-west','["周武王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周文王之子，继承周人势力，联合诸侯伐商。前1046年牧野之战击败商纣王，灭商后建立周王朝并分封宗亲、功臣；不久去世，子成王年幼继位，由周公旦辅政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周武王"}]','武',NULL,'武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-gai','匄','zhou-east','["周敬王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周景王之子、周悼王之弟，前519—前477年在位。即位后王子朝据王城作乱，周敬王一度居于成周，后在晋等诸侯支持下平乱；其晚年三家分晋的局面渐趋形成。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周敬王"}]','敬',NULL,'敬王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-gongsheng','宫湦','zhou-west','["周幽王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周宣王之子，前781—前771年在位。废申后及太子宜臼，改立褒姒为后、伯服为太子；申侯联合缯与犬戎攻周，幽王于骊山一带被杀。前771年镐京失陷，西周结束，诸侯随后拥立宜臼为平王并东迁洛邑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周幽王"}]','幽',NULL,'幽王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-gui','贵','zhou-east','["周景王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周灵王之子，前544—前520年在位。春秋晚期周王室内政与诸侯势力交错；景王死后，王子朝与王子猛争位，王室陷入内乱，王子猛短暂即位为周悼王。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周景王"}]','景',NULL,'景王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-hu','胡','zhou-west','["周厉王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周夷王之子，前877—前841年在位。任用荣夷公推行“专利”，并令卫巫监视议论，引发国人不满；前841年国人暴动，厉王出奔彘地。此后周、召二公行政（另有共伯和摄政说），史称共和。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周厉王"}]','厉',NULL,'厉王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-huqi','胡齐','zhou-east','["周釐王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周庄王之子，亦作周僖王，前681—前677年在位。其在位时间较短，周王室对诸侯的控制已弱，诸侯间兼并与争盟持续发展；死后由其子周惠王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周釐王"}]','釐',NULL,'釐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jian','囏','zhou-west','["周懿王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周共王之子，前899—前892年在位。传世记载称西北戎狄侵扰加剧，周人承受边患；其元年系年与“天再旦”日食记录有关，古史年代存在不同方案。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周懿王"}]','懿',NULL,'懿王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jiao','骄','zhou-east','["周安王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周威烈王之子，前401—前376年在位。周王室已无力约束诸侯，韩、赵、魏持续扩张；三家分晋的政治格局形成后，周天子对诸侯名分的确认更显形式化。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周安王"}]','安',NULL,'安王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jie','介','zhou-east','["周贞定王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周元王之子，前468—前442年在位。周王室衰微之际，晋国韩、赵、魏等卿族逐步掌握实权；周贞定王死后，诸子相继争位，周室政局更加动荡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周贞定王"}]','贞定',NULL,'贞定王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-jing','静','zhou-west','["周宣王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周厉王之子，共和行政结束后于前827年即位，前782年去世。宣王整顿政事、出兵经营边疆，周室一度恢复影响，后世称“宣王中兴”；晚年征戎失利，王室再度显露衰势。其子幽王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周宣王"}]','宣',NULL,'宣王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-lang','阆','zhou-east','["周惠王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周釐王之子，前676—前652年在位。即位初年宠信王子颓，引发王子颓之乱；郑、虢等国出兵平乱后复位。其后周室仍依赖诸侯援助，王权难复西周旧势。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周惠王"}]','惠',NULL,'惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-lin','林','zhou-east','["周桓王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周平王之孙，因父早逝继位，前719—前697年在位。试图收回郑庄公的王室卿士职权，引发周郑交恶；前707年亲率诸侯伐郑，在繻葛战败并受伤，王室威信进一步受损。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周桓王"}]','桓',NULL,'桓王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-man','满','zhou-west','["周穆王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周昭王之子，前976—前923年在位，是西周在位较久的天子之一。传世记载称其曾西巡并与西北诸部交往，也记有征徐、会合诸侯等事；《穆天子传》保存了相关西行叙事，但其内容兼有传说成分。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周穆王"}]','穆',NULL,'穆王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-meng','猛','zhou-east','["周悼王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周景王之子，前520年短暂即位为王，谥悼王。景王死后，王子朝与王子猛争位；悼王在位数月即死，王位由其弟周敬王继承，王子朝之乱仍持续多年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周悼王"}]','悼',NULL,'悼王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-pifang','辟方','zhou-west','["周孝王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周共王之弟，前891—前886年在位，越过懿王一系继位。其时秦人先祖非子为周室养马有功，孝王封其于秦邑，令其延续嬴姓祭祀，是秦国兴起的重要早期背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周孝王"}]','孝',NULL,'孝王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-quji','去疾','zhou-east','["周哀王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周贞定王之子，前441年继位为周哀王，仅三个月即被弟叔袭杀。《史记·周本纪》记其短暂在位，是东周王室继承危机加深的表现。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周哀王"}]','哀',NULL,'哀王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-ren','仁','zhou-east','["周元王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周敬王之子，前476—前469年在位，处于春秋战国之交。此时晋国卿族势力坐大，诸侯兼并加剧；周室政治地位持续下降，史籍对其个人政事少有详载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周元王"}]','元',NULL,'元王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-renchen','壬臣','zhou-east','["周顷王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周襄王之子，前618—前613年在位。继位时东周王室财力与领地有限，诸侯争霸的政治格局已成；在位期间史事记载不多，死后由其子周匡王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周顷王"}]','顷',NULL,'顷王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-shu','叔','zhou-east','["周思王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周贞定王之子，前441年杀兄周哀王而立，称周思王；在位五个月，又被弟嵬所杀。此后嵬即位为周考王，王室短期内连续发生弑立。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周思王"}]','思',NULL,'思王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-song','诵','zhou-west','["周成王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周武王之子，西周第二代天子，前1042—前1021年在位。即位初年由周公旦摄政，管叔、蔡叔与武庚叛乱，后由周公东征平定；亲政后营建雒邑、分封诸侯，巩固周在东方的统治。其子康王继位，二王时期后世称“成康之治”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周成王"}]','成',NULL,'成王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-tuo','佗','zhou-east','["周庄王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周桓王之子，前696—前682年在位。庄王三年，周公黑肩谋立王子克，事泄后被诛，王子克出奔，王室内部政争暂告平息；其子周釐王继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周庄王"}]','庄',NULL,'庄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-wei','嵬','zhou-east','["周考王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周思王之弟，前440—前426年在位。此前周哀王、周思王相继被杀，考王在王室内乱后继位；据《史记·周本纪》，考王封其弟于河南，是东周王畿分裂为西周国的重要背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周考王"}]','考',NULL,'考王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-wu','午','zhou-east','["周威烈王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周考王之子，前425—前402年在位。前403年册命韩、赵、魏为诸侯，史称三家分晋；此举确认了诸侯国卿族裂土自立的既成事实，常被视作战国时代的重要标志。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周威烈王"}]','威烈',NULL,'威烈王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xi','喜','zhou-east','["周烈王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周安王之子，前375—前369年在位。战国诸侯兼并加剧，周王室仅保有洛邑周边王畿，政治影响日益有限；传世记载主要着眼于诸侯兴替，其个人事迹不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周烈王"}]','烈',NULL,'烈王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xia','瑕','zhou-west','["周昭王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周康王之子，前995—前977年在位。史籍记其多次南征荆楚；《竹书纪年》及后世注引记载其南征渡汉水后未能返回，具体死因说法不一。其子穆王继位，昭王时期常被视作周势转衰的开端。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周昭王"}]','昭',NULL,'昭王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xie','燮','zhou-west','["周夷王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周孝王之后继位，前885—前878年在位。关于其个人政事，传世记载较少；《史记·周本纪》记周室此时衰微、诸侯渐强。其后厉王继位，周王室与诸侯关系继续紧张。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周夷王"}]','夷',NULL,'夷王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-xiexin','泄心','zhou-east','["周灵王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周简王之子，前571—前545年在位。其时晋、楚长期争夺诸侯，周王室影响力有限；太子晋早逝，王子贵继位，是为周景王。传世记载还保留了太子晋以直谏闻名的故事。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周灵王"}]','灵',NULL,'灵王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yan','延','zhou-east','["周赧王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周慎靓王之子，东周末代天子，前314—前256年在位。王室分居西周国、东周国，赧王曾迁居西周国并合纵攻秦，未能扭转局势；前256年秦取九鼎、灭西周，赧王卒，周王朝结束。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周赧王"}]','赧',NULL,'赧王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yi','夷','zhou-east','["周简王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周定王之子，前585—前572年在位。春秋中期诸侯会盟与晋楚争霸仍是政治主轴，周王室主要维持礼制与名分；现存史籍关于其个人政事记载有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周简王"}]','简',NULL,'简王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yihu','繄扈','zhou-west','["周共王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周穆王之子，前922—前900年在位。其时西周王室仍维持对诸侯的统治，但传世史籍关于具体政事记载不多；共王之后，王位由其子懿王继承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周共王"}]','共',NULL,'共王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yijiu','宜臼','zhou-east','["周平王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周幽王之子，申侯等拥立为王，与虢公翰所立的周携王并立。前770年东迁洛邑，后世奉其为东周正统；在位至前720年，周室自此以洛邑为中心，王权与领土均较西周大幅收缩。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周平王"}]','平',NULL,'平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yu','瑜','zhou-east','["周定王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周匡王之弟，前606—前586年在位。楚庄王北上问鼎时，王孙满以九鼎象征周室天命，拒绝楚王窥周之意；此事显示周王室名义地位尚存，而实际力量已不及强国。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周定王"}]','定',NULL,'定王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-yuchen','余臣','zhou-east','["周携王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周携王（携惠王），幽王弟；虢公翰等拥立于携，与平王并立；前750年晋文侯杀之。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周携王"}]','携',NULL,'携王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zhao','钊','zhou-west','["周康王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周成王之子，前1020—前996年在位。承接成王时期的政局，延续分封与礼制秩序；《史记》称成康之际天下安宁。其子昭王继位，周王室在昭王时期开始面对南方军事行动与统治压力。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周康王"}]','康',NULL,'康王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zheng','郑','zhou-east','["周襄王"]','姬',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["天子"]','周惠王之子，前651—前619年在位。王子带之乱中被迫出奔，后由晋文公出兵护送复位；周襄王以河阳之会召见诸侯，反映王室权威已须借助霸主维系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周襄王"}]','襄',NULL,'襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('ji-zi','箕子','shang','["胥余"]','子',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","宗室"]','商末宗室，帝辛诸父或庶兄。传说谏纣被囚，武王克商后访之，后走朝鲜。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/箕子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('kong-qiu','丘','zhou-east','[]','子','孔',-551,1,NULL,'year',-479,1,NULL,'year','["思想家"]','孔子，儒家开创者，传统生卒前551–前479年；孔子晚年整理文献、教授弟子；门人记录其言行形成《论语》，成为儒家经典。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孔子"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('mo-xi','妹喜','xia','["末喜","妹嬉"]',NULL,'有施',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','有施氏女，传说夏桀伐有施而得，为桀妃；传统叙事常将其与夏亡并提，事属传说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/妹喜"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-bujiang','不降','xia','["不降"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','泄之子。《史记》载不降崩、弟扃立，是夏世次中少见的兄终弟及。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/不降"}]',NULL,NULL,'不降','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-fa','发','xia','["发","發"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','皋之子，《史记》作帝发，桀之父。《今本竹书纪年》载诸夷宾于王门，事属传说。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/發_(夏朝)"}]',NULL,NULL,'发','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-gao','皋','xia','["皋","昊"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','孔甲之子，《史记》作帝皋；一作昊。正史几乎无事迹。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/皋_(夏朝)"}]',NULL,NULL,'皋','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-huai','槐','xia','["槐","芬","帝宁"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','杼之子，《史记》作帝槐；《今本竹书纪年》等或作芬、帝宁。正史几乎无事迹。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/槐_(夏朝)"}]',NULL,NULL,'槐','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-jie','履癸','xia','["履癸","桀","夏桀"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','发之子，夏朝末代之王，谥号桀。《史记》载其暴虐，鸣条之战为商汤所灭。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/桀"}]','桀',NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-jin','廑','xia','["廑","胤甲"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','扃之子，《史记》作帝廑；《今本竹书纪年》或作胤甲，并载天有妖孽、十日并出，事属传说。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/廑"}]',NULL,NULL,'廑','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-jiong','扃','xia','["扃"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','《史记·夏本纪》称扃为不降之弟，不降死后继位，后由其子廑承统；传世史书没有记下扃的具体政事，夏代年代本身也属于传统纪年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/扃"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]',NULL,NULL,'扃','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-kongjia','孔甲','xia','["孔甲"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','不降之子；扃、廑之后由孔甲继。《史记》称其好方鬼神、事淫乱，夏后氏德衰、诸侯畔之；又有扰龙、刘累御龙传说。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孔甲"}]',NULL,NULL,'孔甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-mang','芒','xia','["芒","荒"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','槐之子，《史记》作帝芒；一作荒。《今本竹书纪年》载其以玄珪宾于河，事属传说。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/芒_(夏朝)"}]',NULL,NULL,'芒','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-qi','启','xia','["启","夏后启"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','禹之子。传统记载益避启，诸侯归启，变禅让为世袭，史称家天下。《尚书·甘誓》载其伐有扈氏。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/启_(夏朝)"}]',NULL,NULL,'启','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-shaokang','少康','xia','["少康"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','相之子，有仍所生。自有虞起兵，与靡灭寒浞，使女艾灭浇、季杼灭豷，恢复夏政，史称少康中兴。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/少康"}]',NULL,NULL,'少康','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-taikang','太康','xia','["太康"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','启之子。《史记》载太康失国；《左传》谓后羿因夏民以代夏政，《五子之歌》托为太康兄弟所作。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/太康_(夏朝)"}]',NULL,NULL,'太康','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-xiang','相','xia','["相"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','仲康之子。寒浞当国时夏后；《左传》载过浇灭斟灌、斟鄩，杀相。后缗方娠逃归有仍，生少康。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/相_(夏朝)"}]',NULL,NULL,'相','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-xie','泄','xia','["泄"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','芒之子，《史记》作帝泄。《今本竹书纪年》载命畎夷、白夷、赤夷、玄夷、风夷、阳夷，事属传说。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/泄"}]',NULL,NULL,'泄','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-yu','禹','xia','["文命","大禹","夏禹"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','夏朝开国之君，姒姓，传说名文命，后世尊称大禹。传说继父鲧治水，受舜禅，都阳城；《史记·夏本纪》以其为夏后氏始。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/禹"}]',NULL,NULL,'禹','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-zhongkang','仲康','xia','["仲康","中康"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','太康之弟，《史记·夏本纪》作中康。后羿代夏之际夏后氏仍记其世次，子为相。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/中康"}]',NULL,NULL,'仲康','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('si-zhu','杼','xia','["杼","予","季杼"]','姒','夏',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','少康之子，《史记》作帝予，亦作杼、季杼。少康中兴时诱杀寒豷于戈；《国语》称其能帅禹，夏后氏报祭。生卒年不详。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/杼"}]',NULL,NULL,'杼','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('tu-shan-shi','涂山氏','xia','["女娇","涂山女"]',NULL,'涂山',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["后妃"]','传说禹之妃、启之母，涂山氏女，或名女娇。《吕氏春秋》有涂山女作歌之说。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/涂山氏"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('wu-xian','巫咸','shang','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家","学者"]','太戊时大臣，与伊陟并治；后世亦传为巫师、星历之祖。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/巫咸"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-yin','尹','shang','["伊挚","阿衡","保衡"]',NULL,'伊',-1649,1,NULL,'year',-1540,1,NULL,'year','["政治家"]','商初重臣，名挚，有莘氏媵臣出身；辅汤灭夏，历外丙、仲壬、太甲、沃丁。传说曾放太甲于桐宫。生卒年代有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伊尹"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yi-zhi','陟','shang','[]',NULL,'伊',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','伊尹之子，太戊时为相。传说亳有祥桑榖合生，伊陟劝太戊修德，殷道复兴。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/伊陟"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhong-hui','仲虺','shang','["莱朱"]',NULL,'薛',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["政治家"]','商汤左相，奚仲之后，居薛；与伊尹并相。《尚书》有仲虺之诰。生卒年不可考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/仲虺"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-dixin','受','shang','["帝辛","纣","受德"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝辛名受，周人谥称纣，是商朝末王。周武王伐商，双方战于牧野；商军败后帝辛死于鹿台，商王朝随之终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/帝辛"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','帝辛,纣',NULL,'','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-diyi','羡','shang','["帝乙"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','帝乙名羡，为文丁之子、帝辛之父。其在位晚期周人势力上升，死后由帝辛继位；关于他与周文王的关系，传世史籍记载存在不同叙述。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/帝乙"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','帝乙',NULL,'商王帝乙','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-gengding','嚣','shang','["庚丁","康丁"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','廪辛之弟，名嚣；甲骨作文丁前的康丁，《史记》作庚丁。四王窗口之末，死年归本王，武乙次年起算。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/康丁"}]','庚丁',NULL,'商王庚丁','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-hedanjia','整','shang','["河亶甲","戔甲"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','河亶甲名整，为外壬之弟。传统记载称其居于相，之后由祖乙继位；早商与中商君主世次主要依据传世文献，年代存在争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/河亶甲"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','河亶甲',NULL,'商河亶甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-linxin','先','shang','["廪辛","冯辛"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','祖甲之子，名先；竹书或作冯辛。与祖庚、祖甲、庚丁同属断代工程前1191–前1148年窗口。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/廪辛"}]','廪辛',NULL,'商王廪辛','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-nangeng','更','shang','["南庚"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','南庚名更，为沃甲之子。祖丁死后继位，传统记载称他将都城迁至奄；其后阳甲即位，商王位继续在旁支间转移。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/南庚"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','南庚',NULL,'商南庚','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-pangeng','旬','shang','["盘庚"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','盘庚名旬，为祖丁之子。即位后将商都迁至殷，面对反对仍坚持迁徙；《史记》称迁殷后百姓安定、商势复兴，殷墟考古为晚商都城提供了重要证据。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/盘庚"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','盘庚','世祖','商盘庚','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-taigeng','辩','shang','["太庚","大庚"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','太庚名辩，又称大庚，是沃丁之弟。其后由子小甲继位；商初兄终弟及的继承叙事见于《史记·殷本纪》，实际年代仍属传统纪年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/太庚"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','太庚',NULL,'商太庚','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-taijia','至','shang','["太甲"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','太甲名至，是商汤之孙、太丁之子。《史记》记伊尹辅政期间曾将他放居桐宫，太甲改过后复位；这段故事也是商初政治传统的重要叙述。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/太甲"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','太甲','太宗','商太甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-taiwu','密','shang','["太戊","大戊"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','雍己之弟，名密，又称大戊；传统称中宗，与伊陟、巫咸辅政而复兴。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/太戊"}]','太戊','中宗','商太戊','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-tang','履','shang','["汤","成汤","天乙","大乙","商汤"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','商汤名履，又称天乙、成汤。传统记载称他联合伊尹等伐夏桀，鸣条之战后建立商朝；《史记·殷本纪》同时保留了其“革命”叙事与早期商世系。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/商汤"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','武','高祖','武王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-waibing','胜','shang','["外丙","卜丙"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','汤之子，太丁之弟。《孟子》《今本竹书纪年》在位二年，《史记》作三年；甲骨或作卜丙。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/外丙"}]','外丙',NULL,'商外丙','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-wairen','发','shang','["外壬","卜壬"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','外壬名发，为仲丁之弟，在商王继承冲突中继位。《史记》称其与河亶甲前后接续，属“九世之乱”时期；甲骨材料有不同释名。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/外壬"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','外壬',NULL,'商外壬','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-wending','托','shang','["文丁","太丁"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文丁名托，为武乙之子、帝乙之父；《史记》称其又作太丁。其后帝乙、帝辛相继，商王朝末期与周势力冲突逐步升级。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/文丁"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','文丁',NULL,'商王文丁','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-woding','绚','shang','["沃丁"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','沃丁名绚，为太甲之子。传统记载称其承统后伊尹去世，沃丁以礼安葬这位辅政大臣；其后由弟太庚继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沃丁"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','沃丁',NULL,'商沃丁','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-wojia','踰','shang','["沃甲","开甲","羌甲"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','沃甲名踰，又称开甲；甲骨材料中的释名与传世文献并不完全一致。他在祖辛之后继位，死后商王位转入祖丁一支，反映商王室继承关系复杂。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/沃甲"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','沃甲',NULL,'商沃甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-wuding','昭','shang','["武丁"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武丁名昭，为小乙之子。传世文献记他任用傅说为相、商势复兴；殷墟甲骨卜辞大量涉及武丁时期，是研究晚商政治与祭祀的重要材料。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/武丁"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','武丁','高宗','商王武丁','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-wuyi','瞿','shang','["武乙"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','庚丁之子，名瞿；晚商之王，断代工程定其在位前1147–前1113年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/武乙"}]','武乙',NULL,'商王武乙','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-xiaojia','高','shang','["小甲"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','小甲名高，为太庚之子。其后商王位在雍己与太戊之间传承，《史记》将这一阶段描述为商道衰微，细节缺少同时代文字材料佐证。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/小甲"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','小甲',NULL,'商小甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-xiaoxin','颂','shang','["小辛"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','小辛名颂，是盘庚之弟。盘庚迁殷后由小辛继位，《史记》称商道再衰；关于这一时期的具体政局，传世记载十分简略。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/小辛"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','小辛',NULL,'商小辛','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-xiaoyi','敛','shang','["小乙"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','小乙名敛，为小辛之弟、武丁之父。传统世系称其死后武丁即位；有关小乙的个人政事，史书没有留下可与武丁时期相比的详细叙述。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/小乙_(商朝)"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','小乙',NULL,'商小乙','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-yangjia','和','shang','["阳甲"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','阳甲名和，为祖丁之子、盘庚之兄。其时商王室继承冲突加深，《史记》称诸侯不朝；阳甲死后由盘庚继位并迁殷。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/阳甲"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','阳甲',NULL,'商阳甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-yongji','伷','shang','["雍己"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','小甲之弟，名伷；传统记载此际诸侯不朝、殷道始衰。甲骨周祭或次太戊之后。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/雍己"}]','雍己',NULL,'商雍己','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zhongding','庄','shang','["仲丁","中丁"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','仲丁名庄，为太戊之子。《史记》称其迁都于嚣，其死后外壬、河亶甲相继，商王室开始出现连续的兄弟继承与政局动荡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/仲丁"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','仲丁',NULL,'商仲丁','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zhongren','庸','shang','["仲壬","中壬"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','汤之子、外丙之弟，亦称中壬。孟子、史记均记在位四年；周祭未见其名，即位与否有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/仲壬"}]','仲壬',NULL,'商仲壬','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zuding','新','shang','["祖丁"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','祖丁名新，为祖辛之子。沃甲死后由祖丁继位，之后南庚承统；《史记》把这几代的兄弟、叔侄相继列为“九世之乱”的背景。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖丁"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','祖丁',NULL,'商祖丁','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zugeng','跃','shang','["祖庚","曜"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武丁之子，名跃，一作曜；甲骨文作「且庚」。具体在位年代尚有争议。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖庚"}]','祖庚',NULL,'商王祖庚','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zujia','载','shang','["祖甲"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','武丁之子、祖庚之弟，名载；甲骨文作「且甲」。与祖庚、廪辛、庚丁同属断代工程前1191–前1148年窗口。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖甲"}]','祖甲',NULL,'商王祖甲','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zuxin','旦','shang','["祖辛"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','祖辛名旦，为祖乙之子、沃甲之兄。传统世系称其死后由弟沃甲继位；具体政事与年代主要依据后世史籍传承。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖辛"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','祖辛',NULL,'商祖辛','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zi-zuyi','滕','shang','["祖乙"]','子','殷',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','祖乙名滕，为河亶甲之子。传统记载称他从相迁至耿，并任用巫贤，商势复振；其后由祖辛继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/祖乙"},{"label":"《史记·夏本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷02"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]','祖乙',NULL,'商祖乙','[]');
