INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('baijia-zhengming','百家争鸣','culture','span',NULL,'approximate_year','approximate_year','百家争鸣是春秋晚期至秦统一前后思想活跃的历史阶段，并无单一明确的起讫年份。',NULL,NULL,NULL,NULL,-551,1,NULL,-6600,-221,12,NULL,-2629,'儒墨道法名等学派并起，塑造此后中国思想传统。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('bigan-killed','比干谏死','politics','point','interpolated_by_other',NULL,NULL,'《今本竹书纪年》将比干之死系于帝辛末年，帝辛在位年数与绝对年代有异说；确切发生年份、月份不详。',-1050,12,NULL,-12577,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'传说比干强谏帝辛，被剖心而死；与微子、箕子并称殷有三仁。',NULL,NULL,'[{"label":"《竹书纪年·帝辛》（中国哲学书电子化计划）","url":"https://ctext.org/zhushu-jinian/di-xin/zh"},{"label":"《史记·殷本纪》（维基文库）","url":"https://zh.wikisource.org/wiki/史記/卷03"}]');
